import{_ as e,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"构建组件 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"组件类定义","slug":"组件类定义","link":"#组件类定义","children":[{"level":3,"title":"组件注册","slug":"组件注册","link":"#组件注册","children":[]}]},{"level":2,"title":"组件属性","slug":"组件属性","link":"#组件属性","children":[{"level":3,"title":"下拉和设置属性","slug":"下拉和设置属性","link":"#下拉和设置属性","children":[]},{"level":3,"title":"页面列表属性","slug":"页面列表属性","link":"#页面列表属性","children":[]}]},{"level":2,"title":"路由参数","slug":"路由参数","link":"#路由参数","children":[]},{"level":2,"title":"处理页面执行周期","slug":"处理页面执行周期","link":"#处理页面执行周期","children":[{"level":3,"title":"页面执行生命周期处理程序","slug":"页面执行生命周期处理程序","link":"#页面执行生命周期处理程序","children":[]},{"level":3,"title":"组件初始化","slug":"组件初始化","link":"#组件初始化","children":[]},{"level":3,"title":"停止响应","slug":"停止响应","link":"#停止响应","children":[]}]},{"level":2,"title":"AJAX 处理程序","slug":"ajax-处理程序","link":"#ajax-处理程序","children":[]},{"level":2,"title":"默认标记","slug":"默认标记","link":"#默认标记","children":[]},{"level":2,"title":"组件部件","slug":"组件部件","link":"#组件部件","children":[{"level":3,"title":"引用\\"自己\\"","slug":"引用-自己","link":"#引用-自己","children":[]},{"level":3,"title":"唯一标识符","slug":"唯一标识符","link":"#唯一标识符","children":[]}]},{"level":2,"title":"从代码渲染部件","slug":"从代码渲染部件","link":"#从代码渲染部件","children":[]},{"level":2,"title":"使用组件注入页面资产","slug":"使用组件注入页面资产","link":"#使用组件注入页面资产","children":[]}],"relativePath":"2.x/zh-cn/plugin/components.md","filePath":"2.x/zh-cn/plugin/components.md"}'),u={name:"2.x/zh-cn/plugin/components.md"};function r(k,n,g,d,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"构建组件",-1)),a(p),n[1]||(n[1]=i(`<p>组件文件和目录位于插件目录的 <strong>/components</strong> 子目录中。 每个组件都有一个定义组件类的 PHP 文件和一个可选的组件部件目录。 组件部件目录名称用小写的组件类名称匹配。 组件目录结构示例：</p><div class="language- extra-class"><pre class="language-text"><code>plugins/
  acme/
    myplugin/
      components/
        componentname/       &lt;=== 部件目录(小写)
          default.htm        &lt;=== 默认标记(可选)
        ComponentName.php    &lt;=== Class文件
      Plugin.php
</code></pre></div><p>组件必须<a href="#oc-component-registration">在插件注册类中注册</a> 使用<code>registerComponents</code> 方法。</p><p><a id="oc-component-class-definition"></a></p><h2 id="组件类定义"><a href="#组件类定义" class="header-anchor">#</a> 组件类定义</h2><p><strong>组件类文件</strong>定义了组件功能和<a href="#oc-component-properties">组件属性</a>。 组件类文件名应与组件类名匹配。 组件类应该扩展<code>\\Cms\\Classes\\ComponentBase</code> 类。 下一个示例中的组件应该在 plugins/acme/blog/components/BlogPosts.php 文件中定义。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Components</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">BlogPosts</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Cms<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ComponentBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">componentDetails</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;博客文章&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;显示博客文章的集合。&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * 帖子在页面上变为可用 {{ component.posts }}
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;First Post&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Second Post&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Third Post&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>componentDetails</code> 方法是必需的。 该方法应该返回一个带有两个键的数组：<code>name</code> 和 <code>description</code>。 名称和描述显示在 CMS 后端用户界面中。</p><p>当这个<a href="./../cms/components.html">组件附加到页面或布局</a> 时，类属性和方法通过组件变量在页面上使用，该名称与组件短名称或别名相匹配。 例如，如果上一个示例中的 BlogPost 组件是在具有其短名称的页面上定义的：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPosts</span><span class="token punctuation">]</span></span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
</code></pre></div><p>你可以通过 <code>blogPosts</code> 变量访问它的 <code>posts</code> 方法。 请注意，Twig 支持方法的属性符号，因此您不需要使用括号。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> blogPosts<span class="token punctuation">.</span>posts <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><a id="oc-component-registration"></a></p><h3 id="组件注册"><a href="#组件注册" class="header-anchor">#</a> 组件注册</h3><p>组件必须通过覆盖<a href="./registration.html#oc-registration-file">插件注册类</a>内的<code>registerComponents</code>方法来注册。 这会告诉 CMS 有关该组件的信息，并提供一个 <strong>短名称</strong> 以供使用。 注册组件的示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerComponents</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Components<span class="token punctuation">\\</span>Todo</span><span class="token operator">::</span><span class="token keyword">class</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;demoTodo&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>这将使用默认别名 <strong>demoTodo</strong> 注册 Todo 组件类。 有关使用组件的更多信息，请参见 <a href="./../cms/components.html">CMS 组件文章</a>。</p><p><a id="oc-component-properties"></a></p><h2 id="组件属性"><a href="#组件属性" class="header-anchor">#</a> 组件属性</h2><p>当您将组件添加到页面或布局时，您可以使用属性对其进行配置。 属性是用组件类的<code>defineProperties</code> 方法定义的。 下一个示例显示如何定义组件属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;最大项目&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;允许的最多待办事项&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validationPattern&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;^[0-9]+$&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validationMessage&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Max Items 属性只能包含数字符号&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>该方法应该返回一个数组，其中属性键作为索引，属性参数作为值。 属性键用于访问组件类中的组件属性值。 属性参数使用具有以下键的数组定义：</p><div class="table"><table tabindex="0"><thead><tr><th>键</th><th>描述</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>必需，属性标题，由CMS后端的组件检查器使用。</td></tr><tr><td><strong>description</strong></td><td>必需，属性描述，由CMS后端的组件检查器使用。</td></tr><tr><td><strong>default</strong></td><td>可选，当组件被添加到 CMS 后端的页面或布局时使用的默认属性值。</td></tr><tr><td><strong>type</strong></td><td>可选，指定属性类型。类型定义了属性在检查器中的显示方式。当前支持的类型有 <strong>string</strong>、<strong>checkbox</strong>、<strong>dropdown</strong> 和 <strong>set</strong>。默认值：<strong>string</strong>。</td></tr><tr><td><strong>validationPattern</strong></td><td>当用户在检查器中输入属性值时使用的可选正则表达式。验证只能与 <strong>string</strong> 属性一起使用。</td></tr><tr><td><strong>validationMessage</strong></td><td>验证失败时显示的可选错误消息。</td></tr><tr><td><strong>required</strong></td><td>可选，强制填充字段。留空时使用validationMessage。</td></tr><tr><td><strong>placeholder</strong></td><td>字符串和下拉属性的可选占位符。</td></tr><tr><td><strong>options</strong></td><td>下拉属性的可选选项数组。</td></tr><tr><td><strong>depends</strong></td><td>下拉属性所依赖的属性名称数组。请参阅下面的 <a href="#oc-dropdown-and-set-properties">下拉属性</a>。</td></tr><tr><td><strong>group</strong></td><td>一个可选的组名。组在检查器中创建部件以简化用户体验。在多个属性中使用相同的组名来组合它们。</td></tr><tr><td><strong>showExternalParam</strong></td><td>为检查器中的属性指定外部参数编辑器的可见性。默认值：<strong>true</strong>。</td></tr></tbody></table></div><p>在组件内部，您可以使用 <code>property</code> 方法读取属性值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果未定义属性值，您可以提供默认值作为 <code>property</code> 方法的第二个参数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">6</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以将所有属性加载为数组：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$properties</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要从组件的 Twig 部件访问属性，请使用引用 Component 对象的 <code>__SELF__</code> 变量：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>property<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>maxItems<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p><a id="oc-dropdown-and-set-properties"></a></p><h3 id="下拉和设置属性"><a href="#下拉和设置属性" class="header-anchor">#</a> 下拉和设置属性</h3><p>下拉列表和设置属性的选项列表可以是静态的或动态的。 静态选项是用属性定义的<code>options</code> 元素定义的。 例子：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;units&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;单位&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;imperial&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;placeholder&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;选择单位&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;options&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;metric&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;公制&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;imperial&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;英制&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>当显示检查器时，可以从服务器动态获取选项列表。 如果在下拉列表或设置属性定义中省略了 <code>options</code> 参数，则选项列表被认为是动态的。 组件类必须定义一个返回选项列表的方法。 该方法应具有以下格式的名称：<code>get*Property*Options</code>，其中 <strong>Property</strong> 是属性名称，例如：<code>getCountryOptions</code>。 该方法返回一个选项数组，其中选项值作为键，选项标签作为值。 动态下拉列表定义示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;country&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;国家&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;us&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getCountryOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;us&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;美国&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ca&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;加拿大&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;zh-cn&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;中华人民共和国&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>动态下拉列表和集合列表可以依赖于其他属性。 例如，州列表可能取决于所选的国家。 依赖项在属性定义中使用 <code>depends</code> 参数声明。 下一个示例定义了两个动态下拉属性，并且州列表取决于国家/地区：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;country&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;国家&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;us&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;State&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dc&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;depends&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;country&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;placeholder&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;选择一个州&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>为了加载州列表，您应该知道当前在检查器中选择了哪个国家。 检查器将所有属性值 POST 到 <code>getPropertyOptions</code> 处理程序，因此您可以执行以下操作：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getStateOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 从 POST 加载国家属性值</span>
    <span class="token variable">$countryCode</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;country&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$states</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;ca&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;ab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;艾伯塔省&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;bc&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;不列颠哥伦比亚省&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;us&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;al&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;阿拉巴马州&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ak&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;阿拉斯加州&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;zh-cn&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;hb&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;河北省&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;hk&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;香港特别行政区&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;tw&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;台湾省&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$states</span><span class="token punctuation">[</span><span class="token variable">$countryCode</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="页面列表属性"><a href="#页面列表属性" class="header-anchor">#</a> 页面列表属性</h3><p>有时组件需要创建指向网站页面的链接。 例如，博客文章列表包含指向博客文章详细信息页面的链接。 在这种情况下，组件应该知道帖子详细信息页面文件名(然后它可以使用 <a href="./../markup/filter-page.html">页面 Twig 过滤器</a>)。 October包括一个用于创建动态下拉列表页面的助手。 下一个示例定义了 postPage 属性，该属性显示页面列表：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;postPage&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;帖子页面&#39;</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dropdown&#39;</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;blog/post&#39;</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getPostPageOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">sortBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;baseFileName&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;baseFileName&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;baseFileName&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="路由参数"><a href="#路由参数" class="header-anchor">#</a> 路由参数</h2><p>组件可以直接访问<a href="./../cms/pages.html#oc-url-syntax">页面的URL</a>中定义的路由参数值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 返回 URL 段值，例如：/page/:post_id</span>
<span class="token variable">$postId</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post_id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在某些情况下，<a href="#oc-component-properties">组件属性</a> 可能充当硬编码值或从 URL 引用该值。</p><p>这个硬编码示例显示了使用标识符&quot;2&quot;的博客文章：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/hard-coded-page</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">id</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">2</span>&quot;</span>
</code></pre></div><p>或者，可以使用 <a href="./../cms/components.html#oc-using-external-property-values">外部属性值</a> 从页面 URL 动态引用该值：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:my_custom_parameter</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">id</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ :my_custom_parameter }}</span>&quot;</span>
</code></pre></div><p>在这两种情况下，都可以使用 <code>property</code> 方法检索值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果需要访问路由参数名称：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 返回 &quot;my_custom_parameter&quot;</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">paramName</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-handling-the-page-execution-cycle"></a></p><h2 id="处理页面执行周期"><a href="#处理页面执行周期" class="header-anchor">#</a> 处理页面执行周期</h2><p>通过覆盖组件类中的<code>onRun</code> 方法，组件可以参与到页面执行循环事件中。 每次页面或布局加载时，CMS 控制器都会执行此方法。 在该方法中，您可以通过 <code>page</code> 属性将变量注入到 Twig 环境中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 当加载页面或布局并将组件附加到它时，将执行此代码。</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">;</span> <span class="token comment">// 向页面注入一些变量</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="页面执行生命周期处理程序"><a href="#页面执行生命周期处理程序" class="header-anchor">#</a> 页面执行生命周期处理程序</h3><p>当页面加载时，October 会执行可以在布局，页面 <a href="./../cms/themes.html#oc-php-section">PHP 部分</a> 和组件类中定义的处理程序函数。 处理程序的执行顺序如下：</p><p>1.布局<code>onInit()</code>函数。 1.页面<code>onInit()</code>函数。 1.布局<code>onStart()</code>函数。 1.布局组件<code>onRun()</code>方法。 1.布局<code>onBeforePageStart()</code>函数。 1.页面<code>onStart()</code>函数。 1.页面组件<code>onRun()</code>方法。 1.页面<code>onEnd()</code>函数。 1.布局<code>onEnd()</code>函数。</p><p><a id="oc-component-initialization"></a></p><h3 id="组件初始化"><a href="#组件初始化" class="header-anchor">#</a> 组件初始化</h3><p>有时您可能希望在组件类第一次实例化时执行代码。 您可以覆盖组件类中的 <code>init</code> 方法来处理任何初始化逻辑，这将在 AJAX 处理程序和页面执行生命周期之前执行。 例如，此方法可用于将另一个组件动态附加到页面。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addComponent</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Components<span class="token punctuation">\\</span>BlogPosts</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blogPosts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="停止响应"><a href="#停止响应" class="header-anchor">#</a> 停止响应</h3><p>和<a href="./../cms/layouts.html#oc-dynamic-layouts">页面执行生命周期</a>中的所有方法一样，如果组件中的<code>onRun</code>方法有返回值，这将在此停止循环 指向并将响应返回给浏览器。 这里我们使用 <code>Response</code> 门面返回一个访问被拒绝的消息：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;拒绝访问!&#39;</span><span class="token punctuation">,</span> <span class="token number">403</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您还可以从 <code>onRun</code> 方法返回 404 响应：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setStatusCode</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">controller</span><span class="token operator">-&gt;</span><span class="token function">run</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;404&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-ajax-handlers"></a></p><h2 id="ajax-处理程序"><a href="#ajax-处理程序" class="header-anchor">#</a> AJAX 处理程序</h2><p>组件可以承载 AJAX 事件处理程序。 它们在组件类中的定义与在 <a href="./../ajax/handlers.html">页面或布局代码</a> 中定义的完全一样。 在组件类中定义的示例 AJAX 处理程序方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onAddItem</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$value1</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value1&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$value2</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$value1</span> <span class="token operator">+</span> <span class="token variable">$value2</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果这个组件的别名是 <em>demoTodo</em> 这个处理程序可以通过 <code>demoTodo::onAddItem</code> 访问。 有关在组件中使用 AJAX 的详细信息，请参阅 <a href="./../ajax/handlers.html#oc-calling-a-handler">调用组件中定义的 AJAX 处理程序</a> 文章。</p><h2 id="默认标记"><a href="#默认标记" class="header-anchor">#</a> 默认标记</h2><p>所有组件都可以带有默认标记，当它包含在带有 <code>{% component %}</code> 标签的页面上时使用，尽管这是可选的。 默认标记保存在 <strong>component partials 目录</strong> 中，该目录与小写的组件类同名。</p><p>默认组件标记应放置在名为 <strong>default.htm</strong> 的文件中。 例如，Demo ToDo 组件的默认标签在文件 <strong>/plugins/october/demo/components/todo/default.htm</strong> 中定义。 然后可以使用 <code>{% component %}</code> 标签将其插入到页面的任何位置：</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;/todo&quot;

[demoTodo]
==
{% component &#39;demoTodo&#39; %}
</code></pre></div><p>默认标记还可以采用在渲染时覆盖 <a href="#oc-component-properties">组件属性</a> 的参数。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>7<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>这些属性在 <code>onRun</code> 方法中将不可用，因为它们是在页面循环完成后建立的。 相反，它们可以通过覆盖组件类中的 <code>onRender</code> 方法来处理。 CMS 控制器在呈现默认标记之前执行此方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 此代码将在默认组件之前执行</span>
    <span class="token comment">// 标记呈现在页面或布局上。</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;允许的最大项目数: &#39;</span> <span class="token operator">.</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-component-partials"></a></p><h2 id="组件部件"><a href="#组件部件" class="header-anchor">#</a> 组件部件</h2><p>除了默认标记之外，组件还可以提供可在前端或默认标记本身内使用的附加部件。如果 Demo ToDo 组件有一个 <strong>pagination</strong> 部件，它将位于 <strong>/plugins/october/demo/components/todo/pagination.htm</strong> 并使用以下命令显示在页面上：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo::pagination<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>可以使用上下文相关的宽松方法。如果在组件部件内部调用，它将直接引用自身。如果在主题部件内部调用，它将扫描页面/布局上使用的所有组件以查找匹配的部件名称并使用它。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>@pagination<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>通过将部件文件放在名为 <strong>components/partials</strong> 的目录中，多个组件可以共享部件。当无法找到常规的组件部件时，在此目录中找到的部件用作后备。例如，位于 <strong>/plugins/acme/blog/components/partials/shared.htm</strong> 的共享部件可以由任何组件使用以下方式显示在页面上：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>@shared<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="引用-自己"><a href="#引用-自己" class="header-anchor">#</a> 引用&quot;自己&quot;</h3><p>组件可以通过使用 <code>__SELF__</code> 变量在它们的部件内部引用自己。默认情况下，它将返回组件的短名称或 <a href="./../cms/components.html#oc-components-aliases">别名</a>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span>__SELF__<span class="token delimiter punctuation">}}</span></span>::onEventHandler<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    [...]
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>组件也可以引用它们自己的属性。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> item <span class="token operator">in</span> __SELF__<span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> item <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>如果在组件部件内部，您需要渲染另一个组件部件，将 <code>__SELF__</code> 变量与部件名称连接起来：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> __SELF__<span class="token operator">~</span><span class="token string"><span class="token punctuation">&quot;</span>::screenshot-list<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="唯一标识符"><a href="#唯一标识符" class="header-anchor">#</a> 唯一标识符</h3><p>如果相同的组件在同一页面上被调用两次，则可以使用 <code>id</code> 属性来引用每个实例。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span>__SELF__<span class="token punctuation">.</span>id<span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>每次显示组件时，ID 都是唯一的。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- ID: demoTodo527c532e9161b --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>

<span class="token comment">&lt;!-- ID: demoTodo527c532ec4c33 --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="从代码渲染部件"><a href="#从代码渲染部件" class="header-anchor">#</a> 从代码渲染部件</h2><p>您可以使用 <code>renderPartial</code> 方法以编程方式在 PHP 代码中渲染组件部件。 这将检查名为<code>component-partial.htm</code>的部件的组件，并将结果作为字符串返回。 第二个参数用于传递视图变量。 当你在 PHP 中渲染组件部件时，同样的 <a href="#oc-component-partials">路径解析逻辑</a> 也适用于 Twig； 使用 <code>@</code> 前缀来引用组件本身内的部件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;约翰·史密斯&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>例如，要将部件渲染为对 <a href="./../ajax/handlers.html">AJAX 处理程序</a> 的响应：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onGetTemplate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#someDiv&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>另一个示例可能是通过从 <code>onRun</code> <a href="#oc-handling-the-page-execution-cycle">页面循环方法</a> 返回一个值来覆盖整个页面视图响应。 此代码将使用 <code>Response</code> 门面专门返回一个 XML 响应：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@default.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;text/xml&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-injecting-page-assets-with-components"></a></p><h2 id="使用组件注入页面资产"><a href="#使用组件注入页面资产" class="header-anchor">#</a> 使用组件注入页面资产</h2><p>组件可以将资产(CSS 和 JavaScript 文件)注入到它们所附加的页面或布局中。 使用控制器的 <code>addCss</code> 和 <code>addJs</code> 方法将资产添加到 CMS 控制器。 它可以在组件的 <code>onRun</code> 方法中完成。 请阅读有关<a href="./../cms/pages.html#oc-injecting-page-assets-programmatically">在页面文章中注入资产</a>的更多详细信息。 例子：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/acme/blog/assets/javascript/blog-controls.js&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果在 <code>addCss</code> 和 <code>addJs</code> 方法参数中指定的路径以斜杠 (/) 开头，那么它将相对于网站根目录。 如果资产路径不以斜杠开头，则它是相对于组件目录的。</p><p><code>addCss</code> 和 <code>addJs</code> 方法提供了第二个参数，用于将注入资产的属性定义为数组。 一个特殊的属性 - <code>build</code> - 可用，它将使用指定插件的当前版本为您注入的资产添加后缀。 这可用于在插件升级时刷新缓存的资产。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/acme/blog/assets/javascript/blog-controls.js&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;build&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Acme.Test&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;defer&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您也可以使用字符串作为第二个参数，然后默认使用字符串值作为 <code>build</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/acme/blog/assets/javascript/blog-controls.js&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Acme.Test&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,121))])}const q=e(u,[["render",r]]);export{v as __pageData,q as default};
